      onSubmit={handleSubmit}
      style={{ display: 'flex', flexDirection: 'column', gap: 16, maxWidth: 360, fontFamily: 'var(--jx-font-sans)' }}
    >
      <JxInputField
        label="Электронная почта"
        type="email"
        name="email"
        required
        placeholder="you@example.com"
        helperText="Раз в неделю, без спама"
